namespace {unsigned checks=0;void Check(bool ok){++checks;if(!ok)throw std::runtime_error("Recording assertion failed.");}template<class F>void Reject(F f){bool rejected=false;try{f();}catch(...){rejected=true;}Check(rejected);}}
int main(){try{Replay::Recording r;r.events={{0,Replay::Kind::Keyboard,30},{10000,Replay::Kind::Keyboard,30,1}};const auto text=Replay::Serialize(r);Check(Replay::Parse(text).events.size()==2);Check(Replay::Csv(r).find("10000,keyboard,30,1")!=std::string::npos);Reject([]{Replay::Parse("{}");});Reject([]{Replay::Parse("{\"schema\":1,\"schema\":1}");});Reject([]{Replay::Parse(std::string(40,'[')+std::string(40,']'));});Reject([&]{auto bad=r;bad.events[0].flags=128;Replay::Validate(bad);});Reject([&]{auto bad=r;bad.events[1].at_us=3600000001ULL;Replay::Validate(bad);});Replay::Held held;held.Accept(r.events[0]);auto released=held.Release();Check(released.size()==1&&released[0].code==30&&(released[0].flags&1));Check(held.Release().empty());held.Accept(r.events[0]);held.Accept(r.events[1]);Check(held.Release().empty());Replay::Event mouse;mouse.kind=Replay::Kind::Mouse;mouse.buttons=1|4|16|64|256;held.Accept(mouse);released=held.Release();Check(released.size()==1&&released[0].buttons==(2|8|32|128|512));std::mt19937 random(1928);for(unsigned run=0;run<10000;++run){Replay::Recording rec;rec.kind=Replay::Kind::Mouse;for(unsigned i=0;i<8;++i){Replay::Event e;e.kind=rec.kind;e.at_us=i*1000;e.x=static_cast<int>(random());e.y=static_cast<int>(random());e.buttons=static_cast<std::uint16_t>(random()&0x3FF);rec.events.push_back(e);}const auto restored=Replay::Parse(Replay::Serialize(rec));Check(restored.events.size()==rec.events.size()&&restored.events[7].x==rec.events[7].x);}std::cout<<checks<<" checks passed. No driver access, capture or replay.\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
